{"code": "import collections, glob, re
counts = collections.Counter()
for path in glob.glob('*.log'):
    with open(path, encoding='utf-8') as f:
        for line in f:
            m = re.match(r'\S+ \S+ ERROR code=(\S+)', line)
            if m:
                counts[m.group(1)] += 1
for code, n in counts.most_common(3):
    print(f'{code}: {n}')
